import{_ as d,a0 as l,w as i,s as n,ao as p,I as r,x as s,a1 as o,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"Linus Torvalds吐槽Fedora项目，连呼数个Stupid！ | LCTT x X-CMD","titleTemplate":false,"description":"Linus Torvalds吐槽Fedora项目，连呼数个Stupid！ | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linus Torvalds吐槽Fedora项目，连呼数个Stupid！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linus Torvalds吐槽Fedora项目，连呼数个Stupid！ | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Linus Torvalds Smashes the Fedora Project, Calls Them Stupid","title":"Linus Torvalds吐槽Fedora项目，连呼数个Stupid！","tag":"201310","desc":""},"relativePath":"201310/Linus Torvalds Smashes the Fedora Project, Calls Them Stupid.md","filePath":"[post].md"}'),u={name:"201310/Linus Torvalds Smashes the Fedora Project, Calls Them Stupid.md"};function T(m,t,L,f,S,v){const e=l("Link");return i(),n("div",null,[t[14]||(t[14]=p('<h1 id="linus-torvalds吐槽fedora项目-连呼数个stupid" tabindex="-1">Linus Torvalds吐槽Fedora项目，连呼数个Stupid！ <a class="header-anchor" href="#linus-torvalds吐槽fedora项目-连呼数个stupid" aria-label="Permalink to “Linus Torvalds吐槽Fedora项目，连呼数个Stupid！”">​</a></h1><p><strong>Linus Torvalds 在Google+上发布了一个非常简单直接的关于Fedora的信息，紧接着就引发了一系列谴责和各式吐槽。</strong></p><p><img src="http://i1-news.softpedia-static.com/images/news2/Linus-Torvalds-Smashes-the-Fedora-Project-Calls-Them-Stupid-393127-2.jpg" alt=""></p><p>Linux之父发布的是一个非常简单的问题：Fedora开发者为何不更新发行版镜像，加入最新的内核与软件包？</p><p>Linus Torvalds说：“为什么你们从来不更新安装镜像呢？难道有什么难言之隐？现在Fedora19的安装镜像还在使用古董级的3.9版内核。这意味着虽然它们能安装在大多数机器上，但是却无法支持像新型笔记本上的无线ID等等这样的功能，所以迁就于通用性完全是不必要的痛苦”。</p><p>问题是这样的，如果你有一台新笔记本，却配了一个老内核，你可能无法完全发挥笔记本的功能，特别是当老内核无法识别无线模块的时候。</p><p>也许更新至新内核是个解决办法，但是为了获取新内核，你得访问互联网，但这是不可能的，因为刚不是说了你的老内核无法识别无线硬件模块吗？于是，如此反复，一个悲剧的怪圈诞生了。当然，如果刚好你的名字叫Linus Torvalds，这个问题就很好解决了，因为你知道如何不通过互联网而是靠自己来编译内核。</p><p>消息发布没多久，一些红帽开发者开始试图解释说，他们负担不起雇人测试的开销，因此无法发布有可能无法工作的镜像。</p><p>Torvalds说，“现在你们说‘我们没法测试镜像’，要我说你们这是[敷衍]，因为现有的旧镜像本来就有问题，所以号称新的镜像有可能出问题，完全是很愚蠢(stupid)的！难道不是吗？”说完这些，Linus还不停嘴，</p><p>他继续说道：“因此，你们所有的说辞都是愚蠢(stupid)的敷衍！你们要做的就是更新Fedora19到Fedora19.x，告知人们它将‘持续更新’，然后停止为本就有问题的镜像寻找愚蠢(stupid)的借口，因为你们压根就没打算测试新镜像是否有问题。”</p>',10)),r("p",null,[t[1]||(t[1]=s("争论双方仍在持续发布新的消息，看起来不远的将来我们就能够看到Fedora的镜像更新了。能翻墙的小伙伴们可以到Linus Torvalds的",-1)),o(e,{href:"https://plus.google.com/102150693225130002912/posts/GqUgcYcfQuV"},{default:a(()=>[...t[0]||(t[0]=[s("Google+页面",-1)])]),_:1}),t[2]||(t[2]=s("去围观一下凑个热闹。",-1))]),t[15]||(t[15]=r("hr",null,null,-1)),r("p",null,[t[4]||(t[4]=s("via: ",-1)),o(e,{href:"http://news.softpedia.com/news/Linus-Torvalds-Smashes-the-Fedora-Project-Calls-Them-Stupid-393127.shtml"},{default:a(()=>[...t[3]||(t[3]=[s("http://news.softpedia.com/news/Linus-Torvalds-Smashes-the-Fedora-Project-Calls-Them-Stupid-393127.shtml",-1)])]),_:1})]),r("p",null,[t[7]||(t[7]=s("译者：",-1)),o(e,{href:"https://blog.csdn.net/tinyeyeser"},{default:a(()=>[...t[5]||(t[5]=[s("Mr小眼儿",-1)])]),_:1}),t[8]||(t[8]=s(" 校对：",-1)),o(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[6]||(t[6]=[s("wxy",-1)])]),_:1})]),r("p",null,[t[11]||(t[11]=s("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[9]||(t[9]=[s("LCTT",-1)])]),_:1}),t[12]||(t[12]=s(" 原创翻译，",-1)),o(e,{href:"http://linux.cn/"},{default:a(()=>[...t[10]||(t[10]=[s("Linux中国",-1)])]),_:1}),t[13]||(t[13]=s(" 荣誉推出",-1))])])}const g=d(u,[["render",T]]);export{h as __pageData,g as default};
